import{z as i,x as d,o as s,c as S,q as n,j as o,D as A,d as E,s as l,S as r,b as e}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"SIMD 扩展：SSE / AVX / NEON","description":"","frontmatter":{"title":"SIMD 扩展：SSE / AVX / NEON","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/simd-extensions.md","filePath":"cs/simd-extensions.md","lastUpdated":1791413859000}'),m={name:"cs/simd-extensions.md"};function B(p,a,D,c,M,V){const t=d("Mermaid");return s(),S("div",null,[a[2]||(a[2]=n('<h1 id="simd-扩展-sse-avx-neon" tabindex="-1">SIMD 扩展：SSE / AVX / NEON <a class="header-anchor" href="#simd-扩展-sse-avx-neon" aria-label="Permalink to &quot;SIMD 扩展：SSE / AVX / NEON&quot;">​</a></h1><div class="epigraph"><p>定宽向量寄存器让一条指令打多个通道：x86 从 128 位 SSE 到 256/512 位 AVX，ARM 用 NEON；控制流仍付一次，数据要排齐。</p><footer>—— 据 Intel SDM；ARM ARM；Hennessy and Patterson, CA:AQA；Flynn, IEEE TC 1972 整理</footer></div><p><a href="/cs/fence-instructions">上一课</a>管标量可见性。体系结构课<a href="/cs/simd-vector">SIMD 与向量</a>已给 DLP 原则。缺口是 <strong>ISA 扩展名</strong>：SSE/AVX 与 NEON 的寄存器与打包算术，接到上一单元的 <a href="/cs/fp-mul-fma">FMA</a> 与<a href="/cs/saturating-arith">饱和</a>，而不是重写 Flynn 分类。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>标量 ISA 循环处理 4 个 float 要四条加。SSE：<code>xmm</code> 128 位 4×float；AVX：<code>ymm</code> 8×；AVX-512：<code>zmm</code> 与掩码。NEON：<code>v</code> 寄存器 128 位。缺口不是「什么是 SIMD」，而是这些扩展如何编码（x86 前缀/VEX/EVEX，ARM 在 A64 里）以及对齐要求（后课 alignment 会收）。</p><p>打包整数饱和乘加对应 DSP 课的端点 MUX，只是铺 \\(W\\) 路。浮点通道遵守 754，异常如何折叠到 MXCSR/FPSR 是实现细节，点名。</p><h3 id="simd-不是-gpu-simt、也不是大模型课" tabindex="-1">SIMD 不是 GPU SIMT、也不是大模型课 <a class="header-anchor" href="#simd-不是-gpu-simt、也不是大模型课" aria-label="Permalink to &quot;SIMD 不是 GPU SIMT、也不是大模型课&quot;">​</a></h3><p>SIMT 多线程束；本课是单线程向量寄存器。不把张量核、注意力算子写进 CS 栏。把 AVX 当「训练加速器产品」，对照课失焦。</p><p><span class="marginnote">Intel SDM 卷 1/2 SIMD 章；ARM NEON。CA:AQA 数据级并行。Flynn 1972 分类名。RVV 下一课才是可变 VL。</span></p><p><span class="marginnote">数字实例：一个 128 位 <code>xmm</code> 装下 4 个 float，\\(256\\) 位 <code>ymm</code> 装 8 个。给 \\(1000\\) 个 float 做加法：标量要 \\(1000\\) 条加法，SSE 要约 \\(250\\) 条，AVX 要 \\(125\\) 条——但前提是这 \\(1000\\) 个数在内存里挨着放。</span></p><p><span class="marginnote">初学者容易把 SIMD 当成多线程。区别在于：SIMD 是<strong>一个线程</strong>里一条指令打多个数据通道，没有锁、没有调度开销；SIMT（GPU）才是成千上万个线程。把 8 个 float 塞进一条 <code>ymm</code> 加法，前后只占一份指令发射带宽。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>编译器自动向量化或内建函数。调用约定：SysV/AAPCS 如何传向量寄存器——ABI 课。上下文切换要保存宽寄存器，<a href="/cs/fpu-lazy">FPU lazy</a> 同类问题放大。内存：连续 load 最快；gather 是 AVX2/AVX-512/SVE 后加，回到不规则。</p>',13)),(s(),o(r,null,{default:A(()=>[l(t,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20SC%5B%22%E6%A0%87%E9%87%8F%E5%BE%AA%E7%8E%AF%22%5D%20--%3E%20PACK%5B%22%E6%89%93%E5%8C%85%E5%88%B0%20xmm%2Fymm%2Fv%22%5D%0A%20%20PACK%20--%3E%20ALU%5B%22%E9%80%9A%E9%81%93%E5%B9%B6%E8%A1%8C%20ALU%2FFMA%22%5D%0A%20%20ALU%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9ARVV%20%E6%8A%8A%E5%AE%BD%E5%BA%A6%E6%94%B9%E6%88%90%20VL%22%5D%0A"})]),fallback:A(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"与 x86 微码：宽指令可能多 μop 或走专用端口。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,[E("下一课 RVV 用 "),e("code",null,"vl"),E(" 动态长度，避免 AVX 的 128/256/512 分代。压缩指令课与 SIMD 正交。本课把工业定宽 SIMD 钉在 ISA 对照轴上。")],-1)),a[6]||(a[6]=e("p",null,"实际向量化循环长什么样？\\(N\\) 个元素很少恰好整除定宽寄存器，编译器靠「主体批量 + 尾部」两段收尾——这就是 AVX-512 掩码存在的理由：",-1)),(s(),o(r,null,{default:A(()=>[l(t,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20N%5B%22%E5%BE%AA%E7%8E%AF%20N%20%E4%B8%AA%20float%22%5D%20--%3E%20B%5B%22%E4%B8%BB%E4%BD%93%EF%BC%9A%E6%AF%8F%E8%BD%AE%E5%90%83%E6%BB%A1%E4%B8%80%E4%B8%AA%E5%90%91%E9%87%8F%3Cbr%3EAVX%20%E6%AF%8F%E8%BD%AE%208%20%E4%B8%AA%22%5D%0A%20%20B%20--%3E%20MORE%7B%22%E5%89%A9%E4%BD%99%20%E2%89%A5%208%20%E4%B8%AA%3F%22%7D%0A%20%20MORE%20--%20%E6%98%AF%20--%3E%20B%0A%20%20MORE%20--%20%E5%90%A6%20--%3E%20T%5B%22%E5%B0%BE%E9%83%A8%E4%B8%8D%E8%B6%B3%E4%B8%80%E4%B8%AA%E5%90%91%E9%87%8F%22%5D%0A%20%20T%20--%3E%20M1%5B%22AVX-512%EF%BC%9A%E6%8E%A9%E7%A0%81%E5%AF%84%E5%AD%98%E5%99%A8%3Cbr%3E%E6%8C%89%E4%BD%8D%E5%85%B3%E6%8E%89%E5%A4%9A%E4%BD%99%E9%80%9A%E9%81%93%22%5D%0A%20%20T%20--%3E%20M2%5B%22%E8%80%81%20ISA%EF%BC%9A%E5%9B%9E%E8%90%BD%E6%A0%87%E9%87%8F%3Cbr%3E%E9%80%90%E4%B8%AA%E5%A4%84%E7%90%86%E5%89%A9%E4%BD%99%E5%85%83%E7%B4%A0%22%5D%0A"})]),fallback:A(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=n('<p>数字实例：\\(N=21\\)、用 AVX（每轮 8 个）——主体跑 2 轮吃掉 16 个，剩 5 个走尾部；掩码寄存器把第 6、7、8 通道关掉，5 个结果照收，不必另写一遍标量循环。</p><p>这一步如果做错了，后果是越界写内存：尾部不设掩码又照整向量写，最后 3 个通道会把数组后面的东西踩掉。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不列全部助记符，不写 AVX-512 许可证政治。不把图像卷积当作业。不进入量化金融向量定价。</p><p>后课默认：SSE/AVX/NEON 是定宽打包 SIMD；FMA 与饱和在通道上重复。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>定宽寄存器打包多元素；编码因 x86/ARM 而异。</li><li>接 FMA 与饱和 ALU，不接 SIMT。</li><li>下一课 RISC-V 向量改可变 VL。</li><li>出处：Intel SDM；ARM ARM；Hennessy and Patterson, CA:AQA；Flynn 1972。</li></ul>',7))])}const u=i(m,[["render",B]]);export{h as __pageData,u as default};
